const SetupCall *zoneSetup(int zone, uint &count) {
	switch (zone) {
	case 1: count = ARRAYSIZE(kSetupSY); return kSetupSY;
	case 2: count = ARRAYSIZE(kSetupNI); return kSetupNI;
	case 3: count = ARRAYSIZE(kSetupRH); return kSetupRH;
	case 4: count = ARRAYSIZE(kSetupFO); return kSetupFO;
	case 5: count = ARRAYSIZE(kSetupRO); return kSetupRO;
	case 6: count = ARRAYSIZE(kSetupWA); return kSetupWA;
	case 7: count = ARRAYSIZE(kSetupAS); return kSetupAS;
	case 8: count = ARRAYSIZE(kSetupN2); return kSetupN2;
	default: count = 0; return nullptr;
	}
}

